//! Detached Attr factories retain genuine owner and document-specific case.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn inert_document_import_main_and_inert_trees_keep_real_target_owners_values_views_and_source(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var source=document.createElement('div');source.setAttribute('data-note','old');source.appendChild(document.createTextNode('\ud800'));document.getElementById('mount').appendChild(source);source.bindingState={held:source};var saved=source.childNodes,original=source.getAttributeNode('data-note'),xml=document.implementation.createDocument(null,''),html=document.implementation.createHTMLDocument('target'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,characterData:true,subtree:true});for(var target of [xml,html,document.createElement('template').content.ownerDocument]){var clone=target.importNode(source,true),list=clone.childNodes,attr=clone.getAttributeNode('data-note');if(clone===source||clone.ownerDocument!==target||clone.parentNode!==null||clone.namespaceURI!=='http://www.w3.org/1999/xhtml'||clone.getAttribute('data-note')!=='old'||clone.firstChild===source.firstChild||clone.firstChild.ownerDocument!==target||clone.firstChild.data.charCodeAt(0)!==0xd800||attr===original||attr.ownerDocument!==target||attr.ownerElement!==clone||clone.bindingState!==undefined||clone.childNodes!==list||list[0]!==clone.firstChild)throw 'actual imported tree and independent target identities';clone.setAttribute('data-note','copy');clone.firstChild.data='copy';if(source.getAttribute('data-note')!=='old'||source.firstChild.data.charCodeAt(0)!==0xd800||watch.takeRecords().length||source.childNodes!==saved)throw 'source data and observation never mutated';var again=xml.importNode(clone,{selfOnly:false});if(again.ownerDocument!==xml||again.firstChild.ownerDocument!==xml||again.getAttribute('data-note')!=='copy'||again.firstChild.data!=='copy')throw 'inert source imports use destination owners';var shallow=target.importNode(source,false);if(shallow.childNodes.length||shallow.getAttribute('data-note')!=='old')throw 'shallow import retains genuine attrs only';}if(xml.documentElement!==null||source.parentNode!==document.getElementById('mount')||original.ownerElement!==source)throw 'import never inserts a root or moves source';
"#);
}
#[test]
fn inert_document_import_exact_foreign_names_leaf_kinds_doctype_and_fragment_topology(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var sourceDoc=document.implementation.createDocument('urn:source','p:Root'),target=document.implementation.createDocument(null,''),raw='\ud800',node=sourceDoc.createElementNS(raw,'P\ud800:Lo\udfff');node.setAttributeNS('urn:attribute','p:Case\udfff','value');node.appendChild(sourceDoc.createCDATASection('CDATA'));node.appendChild(sourceDoc.createComment(raw));node.appendChild(sourceDoc.createProcessingInstruction('original',raw));sourceDoc.documentElement.appendChild(node);var copy=target.importNode(node,true);if(copy.namespaceURI!==raw||copy.prefix!=='P\ud800'||copy.localName!=='Lo\udfff'||copy.tagName!=='P\ud800:Lo\udfff'||copy.ownerDocument!==target||copy.getAttributeNodeNS('urn:attribute','Case\udfff').ownerDocument!==target||copy.childNodes.length!==3||copy.childNodes[0].nodeType!==4||!(copy.childNodes[0] instanceof CDATASection)||copy.childNodes[1].data!==raw||copy.childNodes[2].target!=='original'||copy.childNodes[2].data!==raw)throw 'exact copied namespace and character leaf types';for(var child of copy.childNodes)if(child.parentNode!==copy||child.ownerDocument!==target)throw 'real copied parent and owner';var type=document.implementation.createDocumentType('root','pub','sys'),typeCopy=target.importNode(type);if(typeCopy===type||typeCopy.nodeType!==10||typeCopy.name!=='root'||typeCopy.publicId!=='pub'||typeCopy.systemId!=='sys'||typeCopy.ownerDocument!==target||typeCopy.parentNode!==null)throw 'real detached imported doctype';var fragment=document.createDocumentFragment(),span=document.createElement('span');span.appendChild(document.createTextNode('fragment'));fragment.appendChild(span);var imported=target.importNode(fragment,true);if(!(imported instanceof DocumentFragment)||imported===fragment||imported.ownerDocument!==target||imported.firstChild===span||imported.firstChild.ownerDocument!==target||imported.textContent!=='fragment')throw 'ordinary fragment import kind and topology';var root=target.createElement('root');target.appendChild(typeCopy);target.appendChild(root);root.appendChild(imported);if(imported.childNodes.length||root.firstChild.parentNode!==root||root.textContent!=='fragment'||target.doctype!==typeCopy)throw 'genuine fragment splices and doctype enters target tree';
"#);
}
#[test]
fn inert_document_import_dictionary_reentry_shallow_and_protected_hooks_have_no_prefix(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var target=document.implementation.createHTMLDocument('target'),source=document.createElement('div'),calls=0;source.appendChild(document.createTextNode('before'));var copy=target.importNode(source,{get selfOnly(){calls++;source.firstChild.data='after';return false;}});if(calls!==1||copy.firstChild.data!=='after'||source.firstChild.data!=='after')throw 'dictionary callbacks precede source snapshot';source.appendChild(document.createElement('input'));var shallow=target.importNode(source,{selfOnly:true});if(shallow.childNodes.length||shallow.ownerDocument!==target)throw 'shallow source ignores descendant hook dependency';var caught=false;try{target.importNode(source,true);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||source.childNodes.length!==2||target.body.childNodes.length)throw 'native control hooks remain refused before insertion';var plain=document.createElement('div');caught=false;try{target.importNode(plain,{get selfOnly(){plain.appendChild(document.createElement('template'));return false;}});}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||plain.childNodes.length!==1||target.body.childNodes.length)throw 'postdictionary validation sees actual template dependency';caught=false;try{target.importNode(document,true);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught)throw 'Document import remains prohibited';
"#);
}

#[test]
fn inert_document_import_saved_child_origin_precedes_dictionary_and_new_identity(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var target=document.implementation.createDocument(null,''),source=document.createElement('span');source.appendChild(document.createTextNode('real'));var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Document.prototype.importNode,calls=0,options={get selfOnly(){calls++;return false;}},copy=saved.call(target,source,options);if(copy===source||copy.ownerDocument!==target||copy.firstChild.ownerDocument!==target||copy.textContent!=='real'||calls!==1)throw 'real child realm imported tree';
"#);page.set_location(&crate::navigation::address("https://other-inert-import.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(target,source,options);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls!==1||copy.textContent!=='real'||source.textContent!=='real')throw 'origin guard before import options or records';");
}
